:root {
  --bg-card: #f7f0e3;
  --bg-header: #1e4a5c;
  --bg-specimens: #eef6f4;
  --bg-footer: #2c3e2d;
  --accent-gold: #c9973a;
  --accent-teal: #3a8c7e;
  --text-header-light: #e8dfc8;
  --text-dark: #1a2a1b;
  --text-mid: #3d5247;
  --text-muted: #7a8c80;
  --dot-purple: #7c5cbf;
  --dot-green: #4a9a5c;
  --dot-orange: #d4703a;
  --dot-teal: #3a8c9e;
  --tag-rare-bg: #ede0f5;
  --tag-rare-text: #6a3a9a;
  --tag-common-bg: #dff0e3;
  --tag-common-text: #2e7a3e;
  --tag-uncommon-bg: #fef3e0;
  --tag-uncommon-text: #a06010;
  --border-rule: #b5a07a;
  --meta-bg: #e8dfc8;
}

article.survey-card {
  width: 476px;
  background: var(--bg-card);
  border: 2px solid var(--border-rule);
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background: var(--bg-header);
  padding: 10px 14px;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  border-bottom: 3px solid var(--accent-gold);
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.card-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--accent-gold);
  text-transform: uppercase;
}

.card-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-header-light);
  margin: 0;
  line-height: 1.15;
}

.station-badge {
  width: 46px;
  height: 46px;
  border: 2px solid var(--accent-gold);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.badge-num {
  font-size: 16px;
  font-weight: 900;
  color: var(--accent-gold);
  line-height: 1;
}

.badge-text {
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: var(--text-header-light);
  text-transform: uppercase;
}

.meta-row {
  display: flex;
  flex-direction: row;
  background: var(--meta-bg);
  border-bottom: 1px solid var(--border-rule);
}

.meta-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 6px 4px;
  border-right: 1px solid var(--border-rule);
}

.meta-item:last-child {
  border-right: none;
}

.meta-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--text-muted);
}

.meta-value {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-dark);
  margin-top: 1px;
}

.specimens {
  padding: 8px 14px 10px;
  background: var(--bg-specimens);
  flex: 1;
}

.specimens-title {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent-teal);
  margin: 0 0 6px 0;
}

.specimen-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.specimen-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 7px;
  padding: 4px 8px;
  background: var(--bg-card);
  border-radius: 4px;
  border-left: 3px solid var(--border-rule);
}

.specimen-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dot-purple { background: var(--dot-purple); }
.dot-green  { background: var(--dot-green); }
.dot-orange { background: var(--dot-orange); }
.dot-teal   { background: var(--dot-teal); }

.specimen-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-dark);
  min-width: 118px;
}

.specimen-sci {
  font-size: 10px;
  font-style: italic;
  color: var(--text-muted);
  flex: 1;
}

.specimen-count {
  font-size: 11px;
  font-weight: 800;
  color: var(--text-mid);
  min-width: 18px;
  text-align: right;
}

.specimen-tag {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.4px;
  padding: 2px 5px;
  border-radius: 8px;
  text-transform: uppercase;
}

.tag-rare {
  background: var(--tag-rare-bg);
  color: var(--tag-rare-text);
}

.tag-common {
  background: var(--tag-common-bg);
  color: var(--tag-common-text);
}

.tag-uncommon {
  background: var(--tag-uncommon-bg);
  color: var(--tag-uncommon-text);
}

.card-footer {
  background: var(--bg-footer);
  padding: 7px 14px;
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
}

.footer-item {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.footer-divider {
  width: 1px;
  height: 24px;
  background: var(--accent-teal);
  opacity: 0.5;
}

.footer-label {
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--accent-gold);
}

.footer-value {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-header-light);
}
